/* CZAnim::Resume and Pause, which SOCOM II gave a second parameter (passed 0 here, never
 * narrowed: not a bool) -- their mangled names wait on its type */
extern "C" void func_002709B0(CZAnim *anim, int arg);
extern "C" void func_00270BE0(CZAnim *anim, int arg);

/* SOCOM II's: the wildcard search's state dropped (anim_main.cpp; Close and Open inline it) */
extern "C" void func_002684D0();

/* SOCOM II's: SOCOM 1's NewAnim without the slot's allocation (zanim_set.cpp) */
extern "C" CZAnim *func_0026CAA0(CZAnimSet *set, CZAnim *anim, const char *name);

/* SOCOM II's: an anim's function of one int (0x270570), every anim of a set's (0x26C240) and
 * of every set's (CZAnimMain, 0x26ADA0) -- not named */
extern "C" void func_00270570(CZAnim *anim, int x);
extern "C" int func_0026C240(CZAnimSet *set, int x);

/* CZAnim::Stop, which SOCOM II gave a flag (SOCOM 1: Stop__6CZAnimFv) */
extern "C" void func_002707C0(CZAnim *anim, bool now);

/* SOCOM II's own: steps a FOR_CHILDREN loop to the next child of its node */
extern "C" void func_0025E3F0(_zanim_cmd_hdr *cmd, CZAnim *anim);

/* SOCOM II's own CZAnimMain method (SOCOM 1's if/while had no nesting): moves the current
 * sequence's if-nesting level by `delta`, flags the anim when it leaves 0..255, returns it */
extern "C" int func_002681C0(CZAnimMain *main, int delta);

/* CNode::Rendered, which SOCOM II gave a parameter (2 here) */
extern "C" bool func_00315580(CNode *node, int how);

